def trim_to_tokens(tokenizer, text, target):
    minimum = int(0.9 * target)
    best = None
    for match in re.finditer(r"\S+", text):
        prefix = text[: match.end()]
        ids = tokenizer.encode(prefix)
        if len(ids) > target:
            break
        if len(ids) >= minimum:
            best = (prefix, ids)
    return best


def repeats_short_phrase(ids, max_period=8, repeats=3):
    for period in range(1, max_period + 1):
        span = period * repeats
        for start in range(len(ids) - span + 1):
            if ids[start : start + span] == ids[start : start + period] * repeats:
                return True
    return False


def main():
    parser = argparse.ArgumentParser(description="Choose the benchmark prompts from public-domain prose.")
    parser.add_argument("--model-dir", default="models/gpt2")
    parser.add_argument("--out", default="bench/prompts.json")
    parser.add_argument("--max-new-tokens", type=int, default=MAX_NEW_TOKENS)
    args = parser.parse_args()

    tokenizer = GPT2TokenizerFast.from_pretrained(args.model_dir)
    model = load_model(args.model_dir)

    prompts = []
    failed = []
    for target in TARGETS:
        chosen = None
        fallback = None
        for candidate in CANDIDATES:
            trimmed = trim_to_tokens(tokenizer, candidate["text"], target)
            if trimmed is None:
                continue
            text, prompt_ids = trimmed
            outcome = greedy(model, prompt_ids, args.max_new_tokens)
            print(
                f"p{target:03d} {candidate['source']}: {len(prompt_ids)} tokens, "
                f"min_gap {outcome['min_gap']:.4f}",
                file=sys.stderr,
            )
            if outcome["min_gap"] < 0.05:
                continue
            selection = (candidate["source"], text, prompt_ids, outcome)
            if not repeats_short_phrase(outcome["generated_ids"]):
                chosen = selection
                break
            if fallback is None:
                fallback = selection
        if chosen is None:
            chosen = fallback
        if chosen is None:
            failed.append(target)
            continue

        source, text, prompt_ids, outcome = chosen
        print(
            f"p{target:03d} selected {source} ({len(prompt_ids)} tokens, "
            f"min_gap {outcome['min_gap']:.4f})",
            file=sys.stderr,
        )
        prompts.append({"id": f"p{target:03d}", "text": text})

    if failed:
        print(f"no candidate passed for targets {failed}", file=sys.stderr)
        sys.exit(1)

    payload = {"model": "gpt2", "max_new_tokens": args.max_new_tokens, "prompts": prompts}
    Path(args.out).write_text(json.dumps(payload, indent=2) + "\n")


if __name__ == "__main__":
    main()
